 {
  "id": "terminal",
  "name": "sysinfo",
  "title": "System info",
  "kind": "Terminal",
  "description": "A terminal program: arguments, system stats, processes and MinimaFS files.",
  "files": {
   "main.c": "/*\n * System info - a terminal program.\n *\n * No window: output goes to the Minimal-OS terminal through mos_write.\n * Shows the arguments, system statistics, the process list, the root\n * of the disk, and writes and reads back a file.\n */\n#include \"minimalos.h\"\n#include \"stdio.h\"\n#include \"string.h\"\n\nstatic long info(long op) { return mos_syscall(SYS_SYSINFO, op, 0, 0); }\n\nint main(int argc, char** argv) {\n    printf(\"Hello from a .run program!\\n\");\n    for (int i = 0; i < argc; i++) printf(\"  argv[%d] = %s\\n\", i, argv[i]);\n\n    printf(\"\\nSystem\\n\");\n    printf(\"  cores      %ld\\n\", info(SYS_SYSINFO_CORE_COUNT));\n    printf(\"  cpu usage  %ld%%\\n\", info(SYS_SYSINFO_CPU_USAGE));\n    printf(\"  ram        %ld MB total, %ld MB free\\n\",\n           info(SYS_SYSINFO_RAM_TOTAL) / (1024 * 1024), info(SYS_SYSINFO_RAM_FREE) / (1024 * 1024));\n    printf(\"  uptime     %ld ms\\n\", mos_uptime());\n\n    syscall_process_info_t procs[16];\n    long count = mos_pslist(procs, 16);\n    printf(\"\\nProcesses (%ld)\\n\", count);\n    for (long i = 0; i < count; i++)\n        printf(\"  %lu  %s%s\\n\", procs[i].pid, procs[i].name, procs[i].privilege == SYSCALL_PROC_PRIV_USER ? \"  (user)\" : \"\");\n\n    syscall_dirent_t entries[32];\n    long n = mos_listdir(\"0:/\", entries, 32);\n    printf(\"\\n0:/ (%ld entries)\\n\", n);\n    for (long i = 0; i < n; i++)\n        printf(\"  %s%s\\n\", entries[i].name, entries[i].type == SYSCALL_DIRENT_TYPE_DIR ? \"/\" : \"\");\n\n    const char* path = \"0:/users/hello.txt\";\n    const char* message = \"Written by a Studio-built program.\\n\";\n    if (!mos_exists(path)) mos_create(path, \"text\", \"txt\");\n    long fd = mos_open(path, SYS_O_RDWR);\n    if (fd > 0) {\n        mos_fwrite(fd, message, strlen(message));\n        mos_close(fd);\n    }\n    char buffer[128];\n    fd = mos_open(path, SYS_O_RDONLY);\n    if (fd > 0) {\n        long got = mos_read(fd, buffer, sizeof(buffer) - 1);\n        buffer[got > 0 ? got : 0] = 0;\n        mos_close(fd);\n        printf(\"\\n%s: %s\", path, buffer);\n    }\n    printf(\"\\nBye.\\n\");\n    return 0;\n}\n"
  }
 },
 {
  "id": "fullscreen",
  "name": "shapes",
  "title": "Framebuffer graphics",
  "kind": "Fullscreen",
  "description": "The graphics.h API drawing directly to the screen.",
  "files": {
   "main.c": "/*\n * Fullscreen graphics - the graphics.h API.\n *\n * These calls draw straight to the framebuffer (the SYS_GRAPHICS syscall\n * family), the way programs drew before mosWM existed. The demo animates\n * for ten seconds and then exits.\n */\n#include \"graphics.h\"\n\nint main(void) {\n    uint32_t w = graphics_get_width();\n    uint32_t h = graphics_get_height();\n    uint64_t start = mos_uptime();\n    for (uint32_t frame = 0; mos_uptime() - start < 10000; frame++) {\n        graphics_clear(16, 26, 32);\n        for (uint32_t i = 0; i < 12; i++) {\n            int32_t x = (int32_t)((frame * (i + 2) * 3 + i * 97) % (w + 200)) - 100;\n            int32_t y = (int32_t)(h / 2 + (i % 2 ? 1 : -1) * (int32_t)(i * 22));\n            graphics_fill_circle(x, y, 18 + i * 2, (uint8_t)(60 + i * 15), (uint8_t)(174 - i * 6), 233);\n        }\n        graphics_fill_rectangle(40, 40, 360, 70, 36, 52, 60);\n        graphics_rectangle(40, 40, 360, 70, 61, 174, 233);\n        graphics_text(\"Minimal-OS framebuffer graphics\", 56, 58, 255, 255, 255);\n        graphics_text(\"graphics_fill_circle / graphics_text / ...\", 56, 82, 155, 175, 188);\n        graphics_fill_triangle((int32_t)w - 160, (int32_t)h - 60, (int32_t)w - 60, (int32_t)h - 60,\n                               (int32_t)w - 110, (int32_t)h - 150, 232, 179, 76);\n        graphics_line(0, (int32_t)h - 20, (int32_t)w, (int32_t)h - 20, 74, 191, 138);\n        graphics_present(0, 0, (int32_t)w, (int32_t)h);\n        mos_sleep(33);\n    }\n    mos_exit();\n}\n"
  }
 }
